module.exports = local_settings

// this device's settings as synced keys: dconf keys from the allowed dirs + keys owned by
// sources like /extensions/<uuid>, /wallpaper/... and /themes/... (read_all, write, owns, optional prepare)
function local_settings ({ dconf, rules, sources }) {
  const api = { read_all, write, prepare, dump: () => dconf.dump('/') }
  return api

  async function read_all () {
    const all = {}
    for (const source of sources) Object.assign(all, await source.read_all())
    for (const dir of rules.allowed_dirs) Object.assign(all, await dconf.read_dir(dir))
    return all
  }

  // null means reset (for sources: they decide, nothing is ever deleted)
  function write (key, value) {
    const source = sources.find(s => s.owns(key))
    if (source) return source.write(key, value)
    return value === null ? dconf.reset(key) : dconf.write(key, value)
  }

  // before a key is sent, its source can share a file (the wallpaper image, a theme folder)
  async function prepare (key, value) { await sources.find(s => s.owns(key))?.prepare?.(key, value) }
}
